package app.overfit.data.catalog

import app.overfit.data.KeyValueStore
import app.overfit.data.db.ExerciseCatalogFields
import app.overfit.data.db.ExerciseEntity
import app.overfit.data.db.OverfitDatabase
import app.overfit.data.db.transaction
import app.overfit.domain.ExerciseSource
import app.overfit.domain.TrackingType
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json

/** Format of files/catalog/exercises.json (generated by tools/catalog/import_catalog.py). */
@Serializable
data class CatalogFile(val version: String, val exercises: List<CatalogExercise>)

@Serializable
data class CatalogExercise(
    val id: String,
    val name: String,
    val source: ExerciseSource,
    val image: String? = null,
    val primary: List<String> = emptyList(),
    val secondary: List<String> = emptyList(),
    val equipment: String? = null,
    val tracking: TrackingType,
    /** IDs of merged free-exercise-db duplicates (for traceability only). */
    val merged: List<String> = emptyList(),
)

/**
 * Loads the bundled catalogue into the database whenever its version changes.
 * New exercises are inserted; existing ones only get their catalogue fields (name, image, muscles,
 * equipment) updated. Tracking type, rest time and archive state, which the user can change, are
 * kept. Exercises that disappear from the catalogue are never deleted (templates and workouts may
 * reference them).
 */
class CatalogSeeder(
    private val db: OverfitDatabase,
    private val kv: KeyValueStore,
    /** Reads the raw catalogue JSON (Compose resource in the app, a file in tests). */
    private val readCatalog: suspend () -> ByteArray,
) {
    suspend fun seedIfNeeded(now: Long): Boolean {
        val catalog = load()
        if (kv.get(KEY_VERSION) == catalog.version && db.exerciseDao().count() > 0) return false
        seed(catalog, now)
        kv.put(KEY_VERSION, catalog.version)
        return true
    }

    suspend fun load(): CatalogFile = parse(readCatalog())

    suspend fun seed(catalog: CatalogFile, now: Long) {
        val dao = db.exerciseDao()
        db.transaction {
            dao.insertIgnore(
                catalog.exercises.map {
                    ExerciseEntity(
                        id = it.id,
                        name = it.name,
                        source = it.source,
                        imageRef = it.image,
                        primaryMuscles = it.primary,
                        secondaryMuscles = it.secondary,
                        equipment = it.equipment,
                        trackingType = it.tracking,
                        defaultRestSec = null,
                        createdAt = now,
                        updatedAt = now,
                    )
                },
            )
            dao.updateCatalogFields(
                catalog.exercises.map {
                    ExerciseCatalogFields(
                        id = it.id,
                        name = it.name,
                        source = it.source,
                        imageRef = it.image,
                        primaryMuscles = it.primary,
                        secondaryMuscles = it.secondary,
                        equipment = it.equipment,
                        updatedAt = now,
                    )
                },
            )
        }
    }

    companion object {
        /** Path inside Compose resources (`Res.readBytes(RESOURCE_PATH)`). */
        const val RESOURCE_PATH = "files/catalog/exercises.json"
        const val KEY_VERSION = "overfit.catalog.version"
        private val json = Json { ignoreUnknownKeys = true }

        fun parse(bytes: ByteArray): CatalogFile = json.decodeFromString(CatalogFile.serializer(), bytes.decodeToString())
    }
}
